import { useState } from 'preact/hooks';
import { render } from 'preact';
import { setupRerender } from 'preact/test-utils';
import { html } from '../../src/util';

describe('debug scratch', () => {
	let scratch;

	beforeEach(() => {
		scratch = document.createElement('div');
		document.body.appendChild(scratch);
	});

	afterEach(() => {
		render(null, scratch);
		scratch.remove();
	});

	it('debug scenario', () => {
		let setChild, setParent, renders;
		const Child = props => {
			renders = (renders || 0) + 1;
			console.log('[Child render] props.text =', props.text, 'render#', renders);
			const [, setState] = useState(false);
			setChild = setState;
			return <p>{props.text}</p>;
		};

		const Parent = () => {
			const [state, setState] = useState('hello world');
			setParent = setState;
			console.log('[Parent render] state =', state);
			return <Child text={state} />;
		};

		const rerender = setupRerender();
		render(<Parent />, scratch);
		console.log('--- initial:', scratch.innerHTML);

		console.log('--- setParent(hello world!!!)');
		setParent('hello world!!!');
		console.log('--- setChild(true)');
		setChild(true);
		console.log('--- setChild(false)');
		setChild(false);
		console.log('--- rerender()');
		rerender();
		console.log('--- result:', scratch.innerHTML);
	});
});

